public class Song {
    private String title;
    private String artist;
    private String genre;
    private int energy;

    public Song(String title, String artist, String genre, int energy) {
        this.title = title;
        this.artist = artist;
        this.genre = genre;
        this.energy = energy;
    }

    public String getTitle() {
        return title;
    }

    public String getArtist() {
        return artist;
    }

    public String getGenre() {
        return genre;
    }

    public int getEnergy() {
        return energy;
    }

    @Override
    public String toString() {
        return title + " by " + artist + " (" + genre + ", energy " + energy + ")";
    }
}
